const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed=[['Revenue','IID','Toàn khối','Giám đốc IID',null,40,120,'tỷ VNĐ','up','Báo cáo tài chính',96],['Gross Profit','IID','Toàn khối','Giám đốc IID',null,30,36,'tỷ VNĐ','up','Báo cáo tài chính',31],['Gross Margin','IID','Toàn khối','Giám đốc IID',null,15,30,'%','up','Báo cáo tài chính',28],['NRR','IID','Toàn khối','Giám đốc IID',null,15,110,'%','up','CRM',106],['Doanh thu khách hàng mới','Bộ phận','Kinh doanh','Trưởng phòng kinh doanh','k0',60,48,'tỷ VNĐ','up','CRM',39],['Tỷ lệ gia hạn','Bộ phận','Kinh doanh','Trưởng phòng kinh doanh','k3',40,95,'%','up','CRM',88],['Biên lợi nhuận dịch vụ','Bộ phận','Vận hành','Trưởng phòng vận hành','k2',50,32,'%','up','Báo cáo vận hành',30],['Churn khách hàng','Bộ phận','Vận hành','Trưởng phòng vận hành','k3',50,5,'%','down','CRM',6.2],['Doanh thu danh mục phụ trách','Cá nhân','Kinh doanh','Nguyễn Minh Anh','k4',60,12,'tỷ VNĐ','up','CRM',9.5],['Gia hạn khách hàng phụ trách','Cá nhân','Kinh doanh','Nguyễn Minh Anh','k5',40,95,'%','up','CRM',92]].map((r,i)=>({id:'k'+i,name:r[0],level:r[1],team:r[2],owner:r[3],parent:r[4],weight:r[5],target:r[6],unit:r[7],direction:r[8],source:r[9],frequency:'Hàng tháng',updates:{10:{actual:r[10],note:'Số liệu mẫu minh họa'}}}));
let state;try{state=JSON.parse(localStorage.getItem('iid-kpi-v1'))}catch{}state=state||{kpis:seed,reviews:{},mix:{department:[50,50],personal:[30,40,30]}};let view='overview',month=10,editing=null,updating=null;const save=()=>{localStorage.setItem('iid-kpi-v1',JSON.stringify(state))},toast=t=>{$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)};
const actual=k=>k.updates[month]?.actual,score=k=>{let a=actual(k);return a==null?null:k.direction==='up'?a/k.target*100:a===0?120:k.target/a*100},num=n=>n==null?'—':Number(n).toLocaleString('vi-VN',{maximumFractionDigits:1});const group=k=>k.level==='IID'?'IID':k.level+' · '+k.team+' · '+k.owner;const groups=()=>Object.groupBy(state.kpis,group);const gscore=ks=>{if(!ks.length||ks.some(k=>score(k)==null)||Math.abs(ks.reduce((s,k)=>s+k.weight,0)-100)>.01)return null;return ks.reduce((s,k)=>s+Math.min(120,score(k))*k.weight/100,0)};const status=k=>score(k)==null?'<span class="badge warn">Chưa cập nhật</span>':`<span class="badge ${score(k)<80?'bad':score(k)<100?'warn':''}">${score(k)>=100?'Đạt mục tiêu':score(k)>=80?'Đang theo dõi':'Cần chú ý'}</span>`;
function head(title,desc,action=true){return `<div class="titlebar"><div><div class="eyebrow">CÙNG HƯỚNG MỤC TIÊU CHUNG</div><h1>${title}</h1><p>${desc}</p></div>${action?'<button class="primary" onclick="openEditor()">+ Tạo KPI mới</button>':''}</div>`}
function issues(){let a=[];Object.entries(groups()).forEach(([g,ks])=>{let w=ks.reduce((s,k)=>s+k.weight,0);if(Math.abs(w-100)>.01)a.push(`${g}: tổng trọng số ${num(w)}%, cần bằng 100%.`)});state.kpis.forEach(k=>{if(k.level!=='IID'&&!state.kpis.some(p=>p.id===k.parent&&p.level===(k.level==='Bộ phận'?'IID':'Bộ phận')))a.push(`${k.name}: liên kết cấp trên không hợp lệ.`)});return a}
function rows(ks){return ks.length?`<div class="tablewrap"><table><thead><tr><th>KPI / CHỦ SỞ HỮU</th><th>CẤP / BỘ PHẬN</th><th>TRỌNG SỐ</th><th>MỤC TIÊU NĂM</th><th>KẾT QUẢ T${month}</th><th>HOÀN THÀNH</th><th>TRẠNG THÁI</th><th>THAO TÁC</th></tr></thead><tbody>${ks.map(k=>`<tr><td><strong>${esc(k.name)}</strong><small>${esc(k.owner)} · ${esc(k.source)}</small></td><td>${esc(k.level)}<small>${esc(k.team)}</small></td><td>${num(k.weight)}%</td><td>${num(k.target)} ${esc(k.unit)}<small>${k.direction==='down'?'↓ Càng thấp càng tốt':'↑ Càng cao càng tốt'}</small></td><td>${num(actual(k))}<small>${esc(k.updates[month]?.note||'')}</small></td><td>${num(score(k))}${score(k)!=null?'%':''}<div class="track"><div class="fill" style="width:${Math.min(100,score(k)||0)}%"></div></div></td><td>${status(k)}</td><td><button onclick="openUpdate('${k.id}')">Cập nhật</button> <button onclick="openEditor('${k.id}')">Sửa</button> <button onclick="removeKpi('${k.id}')" aria-label="Xóa ${esc(k.name)}">×</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Chưa có KPI phù hợp.</div>'}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));let ks=state.kpis,done=ks.filter(k=>actual(k)!=null).length,gs=gscore(ks.filter(k=>k.level==='IID')),warnings=issues();if(view==='overview')$('#app').innerHTML=head('Tổng quan hiệu suất','Theo dõi mục tiêu, kết nối đóng góp và chủ động cải thiện.')+`<div class="hero"><div><div class="eyebrow">KẾ HOẠCH 2027 · KHỐI IID</div><h2>Một mục tiêu chung. Mỗi đóng góp đều có ý nghĩa.</h2><p>Kết nối xuyên suốt từ toàn khối đến từng cá nhân.</p></div><div class="art">↗</div></div><div class="stats"><div class="card"><small>ĐIỂM KPI TOÀN IID</small><div class="number">${num(gs)}<small> / 100</small></div><p>Điểm theo trọng số · Trần 120%</p></div><div class="card"><small>MỤC TIÊU ĐANG QUẢN LÝ</small><div class="number">${ks.length}</div><p>Trong 3 tầng KPI liên kết</p></div><div class="card"><small>ĐÃ CẬP NHẬT THÁNG ${month}</small><div class="number">${done}<small> / ${ks.length}</small></div><p>${ks.length?Math.round(done/ks.length*100):0}% KPI có kết quả</p></div><div class="card"><small>KPI CẦN CHÚ Ý</small><div class="number">${ks.filter(k=>score(k)!=null&&score(k)<80).length}</div><p>Mức hoàn thành dưới 80%</p></div></div><div class="panels"><div class="panel"><div class="paneltitle"><h2>Hiệu suất theo nhóm</h2><small>Tháng ${month} / 2027</small></div>${Object.entries(groups()).map(([g,a])=>`<div class="progressrow"><span>${esc(g)}</span><div class="track"><div class="fill" style="width:${Math.min(100,gscore(a)||0)}%"></div></div><strong>${num(gscore(a))}%</strong></div>`).join('')}<p class="mini">Chỉ tính điểm khi trọng số bằng 100% và tất cả KPI trong nhóm có kết quả.</p></div><div class="panel"><h2>Cần bạn quan tâm</h2>${warnings.map(w=>`<div class="alert">${esc(w)}</div>`).join('')}${ks.filter(k=>score(k)==null||score(k)<100).slice(0,4).map(k=>`<div class="alert"><strong>${esc(k.name)}</strong><br>${esc(k.owner)} · ${num(score(k))}% <button onclick="openUpdate('${k.id}')">Cập nhật</button></div>`).join('')||'<p>Tất cả KPI đã đạt mục tiêu.</p>'}</div></div><div class="sectionspace"><div class="paneltitle"><h2>KPI toàn khối IID</h2><button onclick="view='kpis';render()">Xem tất cả →</button></div>${rows(ks.filter(k=>k.level==='IID'))}</div>`;
if(view==='kpis'){$('#app').innerHTML=head('Sổ KPI','Quản lý mục tiêu đo lường được, người phụ trách và kết quả thực tế.')+warnings.map(w=>`<div class="alert">${esc(w)}</div>`).join('')+'<div class="toolbar"><input id="search" placeholder="Tìm KPI, chủ sở hữu hoặc bộ phận…"><select id="level"><option value="">Tất cả các cấp</option><option>IID</option><option>Bộ phận</option><option>Cá nhân</option></select><select id="filterstatus"><option value="">Tất cả trạng thái</option><option value="missing">Chưa cập nhật</option><option value="risk">Dưới 80%</option><option value="achieved">Đạt mục tiêu</option></select></div><div id="results"></div>';let filter=()=>{let q=$('#search').value.toLowerCase(),l=$('#level').value,s=$('#filterstatus').value;$('#results').innerHTML=rows(ks.filter(k=>(!l||k.level===l)&&[k.name,k.owner,k.team].join(' ').toLowerCase().includes(q)&&(!s||s==='missing'&&score(k)==null||s==='risk'&&score(k)!=null&&score(k)<80||s==='achieved'&&score(k)>=100)))};['search','level','filterstatus'].forEach(id=>$('#'+id).oninput=filter);filter()}
if(view==='cascade')$('#app').innerHTML=head('Liên kết mục tiêu','Mỗi KPI bộ phận và cá nhân đều đóng góp vào mục tiêu cấp trên.')+`<div class="panel"><h2>Cơ cấu điểm đánh giá tổng hợp</h2><p>Điểm nhóm ở Tổng quan là điểm KPI riêng. Cơ cấu dưới đây dùng cho đánh giá tổng hợp; cần có đủ điểm các cấp và tổng trọng số 100%.</p><div class="guidegrid">${mixform('department','Bộ phận',['IID','Bộ phận'],[[30,70],[30,70]])}${mixform('personal','Cá nhân',['IID','Bộ phận','Cá nhân'],[[20,40],[30,50],[20,40]])}</div></div><div class="sectionspace">${ks.filter(k=>k.level==='IID').map(k=>`<div class="treeitem"><span class="badge">IID</span> <strong>${esc(k.name)}</strong> · ${num(score(k))}%<div class="tree">${ks.filter(c=>c.parent===k.id).map(c=>`<div class="treeitem"><span class="badge">Bộ phận</span> ${esc(c.name)} <small>· ${esc(c.team)}</small><div class="tree">${ks.filter(p=>p.parent===c.id).map(p=>`<div class="treeitem"><span class="badge">Cá nhân</span> ${esc(p.name)} · ${esc(p.owner)}</div>`).join('')||'<p class="mini">Chưa có KPI cá nhân liên kết.</p>'}</div></div>`).join('')||'<p class="mini">Chưa có KPI bộ phận liên kết.</p>'}</div></div>`).join('')}</div>`;
if(view==='review'){let quarter=Math.ceil(month/3);$('#app').innerHTML=head(`Đánh giá quý ${quarter}`,'Ghi nhận kết quả, phản hồi của leader và hành động cho kỳ tiếp theo.',false)+`<div class="alert">Điểm tham khảo sử dụng tháng ${month}, là tháng đang chọn. Đây không phải trung bình quý. Trạng thái đánh giá được lưu riêng cho từng quý.</div>`+Object.entries(groups()).map(([g,a],i)=>{let key=`${quarter}|${g}`,r=state.reviews[key]||{};return `<div class="panel reviewcard"><div class="paneltitle"><h2>${esc(g)}</h2><span class="badge">Điểm KPI riêng: ${num(gscore(a))}%</span></div><p class="mini">${esc(composite(g,a))}</p><label>Nhận xét & kế hoạch hành động<textarea id="review${i}" placeholder="Kết quả nổi bật, nguyên nhân chênh lệch, hành động và thời hạn…">${esc(r.note||'')}</textarea></label><select id="rs${i}" aria-label="Trạng thái đánh giá"><option ${r.status==='Nháp'?'selected':''}>Nháp</option><option ${r.status==='Đã đánh giá'?'selected':''}>Đã đánh giá</option></select><button class="primary" onclick="saveReview(${i},'${encodeURIComponent(key)}')">Lưu đánh giá</button></div>`}).join('')}
if(view==='guide')$('#app').innerHTML=head('Nguyên tắc triển khai','Chuyển nội dung “KPI 2027 — Khối IID” thành một quy trình quản lý nhất quán.',false)+`<div class="guidegrid"><div class="panel"><h2>01 · Cấu trúc 3 tầng</h2><p>IID: Revenue, GP, GM%, Renewal / NRR / Churn.<br>Bộ phận: KPI chung của IID và 3–5 KPI đặc thù.<br>Cá nhân: KPI khối, KPI bộ phận và đóng góp cá nhân.</p></div><div class="panel"><h2>02 · Trọng số & liên kết</h2><p>Tổng trọng số luôn bằng 100%. Bộ phận: IID 30–70%, bộ phận 30–70%. Cá nhân: IID 20–40%, bộ phận 30–50%, cá nhân 20–40%. Điều chỉnh theo vai trò và mức độ ảnh hưởng.</p></div><div class="panel"><h2>03 · Nhịp triển khai</h2><p>Chốt KPI IID → Cascade xuống bộ phận → Bổ sung 3–5 KPI đặc thù → Cascade đến cá nhân → Cập nhật hàng tháng, review hàng quý.</p></div><div class="panel"><h2>04 · Cách tính điểm trong ứng dụng</h2><p>Tăng là tốt: thực tế / mục tiêu × 100%. Giảm là tốt: mục tiêu / thực tế × 100%; thực tế bằng 0 cho 120%. Điểm trọng số chặn ở 120%. Mục tiêu hiện là mục tiêu năm; nhập kết quả lũy kế cho chỉ tiêu lũy kế. Đây là quy ước triển khai bổ sung, có thể điều chỉnh theo chính sách công ty.</p></div><div class="panel"><h2>05 · Dữ liệu & sử dụng</h2><p>Dữ liệu ban đầu là minh họa. Lưu trên trình duyệt và thiết bị hiện tại; chưa có đồng bộ nhóm hoặc phân quyền tài khoản. Xuất JSON để sao lưu và nhập lại khi chuyển thiết bị. CSV phục vụ báo cáo.</p></div><div class="panel"><h2>06 · Lưu ý cho leader</h2><p>Ưu tiên outcome hơn activity. Mỗi KPI cần target, owner, nguồn dữ liệu và tần suất cập nhật. Tập trung vào chỉ số trọng yếu và giúp mỗi cá nhân thấy rõ đóng góp vào mục tiêu chung.</p></div></div>`}
function mixform(key,title,labels,bounds){return `<form onsubmit="saveMix(event,'${key}')"><h3>${title}</h3>${labels.map((l,i)=>`<label>${l} (${bounds[i][0]}–${bounds[i][1]}%)<input name="v${i}" type="number" min="${bounds[i][0]}" max="${bounds[i][1]}" value="${state.mix[key][i]}" required></label>`).join('')}<p><button>Lưu cơ cấu</button></p></form>`}
function saveMix(e,key){e.preventDefault();let vals=[...new FormData(e.target).values()].map(Number);if(vals.reduce((s,v)=>s+v,0)!==100)return toast('Tổng cơ cấu phải bằng 100%.');state.mix[key]=vals;save();toast('Đã lưu cơ cấu đánh giá');}
function composite(g,ks){if(ks[0].level==='IID')return 'Điểm toàn khối IID.';let iid=gscore(state.kpis.filter(k=>k.level==='IID')),own=gscore(ks),dept=ks[0].level==='Cá nhân'?gscore(state.kpis.filter(k=>k.level==='Bộ phận'&&k.team===ks[0].team)):own,mix=state.mix[ks[0].level==='Cá nhân'?'personal':'department'],vals=ks[0].level==='Cá nhân'?[iid,dept,own]:[iid,own];if(vals.some(v=>v==null))return 'Chưa đủ dữ liệu hoặc trọng số để tính điểm tổng hợp.';return 'Điểm tổng hợp theo cơ cấu: '+num(vals.reduce((s,v,i)=>s+v*mix[i]/100,0))+'%.'}
function saveReview(i,key){state.reviews[decodeURIComponent(key)]={note:$('#review'+i).value,status:$('#rs'+i).value};save();toast('Đã lưu đánh giá quý')}
function parentOptions(){let f=$('#form'),level=f.elements.level.value;f.elements.parent.innerHTML='<option value="">Không có cấp trên</option>'+state.kpis.filter(k=>k.id!==editing&&k.level===(level==='Cá nhân'?'Bộ phận':'IID')&&level!=='IID').map(k=>`<option value="${k.id}">${esc(k.name)} · ${esc(k.team)}</option>`).join('');f.elements.parent.required=level!=='IID'}
function openEditor(id){editing=id||null;$('#form').reset();$('#formtitle').textContent=id?'Chỉnh sửa KPI':'Tạo KPI';let k=state.kpis.find(k=>k.id===id);if(k)for(let n of ['name','level','team','owner','weight','target','unit','direction','source','frequency'])$('#form').elements[n].value=k[n];parentOptions();if(k)$('#form').elements.parent.value=k.parent||'';$('#editor').showModal()}
$('#form').elements.level.onchange=parentOptions;$('#close').onclick=()=>$('#editor').close();$('#form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.target=Number(d.target);d.weight=Number(d.weight);d.parent=d.parent||null;let old=state.kpis.find(k=>k.id===editing);if(old&&old.level!==d.level&&state.kpis.some(k=>k.parent===old.id))return toast('Hãy sửa liên kết KPI con trước khi thay đổi cấp.');if(d.level==='IID')d.parent=null;let k={...d,id:editing||crypto.randomUUID(),updates:old?.updates||{}};if(old)state.kpis[state.kpis.indexOf(old)]=k;else state.kpis.push(k);save();$('#editor').close();render();toast('Đã lưu KPI. Kiểm tra tổng trọng số của nhóm.');};
function removeKpi(id){if(state.kpis.some(k=>k.parent===id))return toast('KPI còn mục tiêu con. Hãy đổi liên kết của chúng trước.');if(!confirm('Xóa KPI và toàn bộ kết quả của KPI này?'))return;state.kpis=state.kpis.filter(k=>k.id!==id);save();render()}
function openUpdate(id){updating=id;let k=state.kpis.find(k=>k.id===id),u=k.updates[month];$('#updatename').textContent=`${k.name} · Tháng ${month}/2027 · ${k.unit}`;$('#updateform').reset();$('#updateform').elements.actual.value=u?.actual??'';$('#updateform').elements.note.value=u?.note||'';$('#update').showModal()}
$('#updateform').onsubmit=e=>{e.preventDefault();let k=state.kpis.find(k=>k.id===updating);k.updates[month]={actual:Number(e.target.elements.actual.value),note:e.target.elements.note.value};save();$('#update').close();render();toast('Đã cập nhật kết quả tháng '+month)};
$('#month').innerHTML=Array.from({length:12},(_,i)=>`<option value="${i+1}" ${i+1===month?'selected':''}>Tháng ${String(i+1).padStart(2,'0')} / 2027</option>`).join('');$('#month').onchange=e=>{month=Number(e.target.value);render()};document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});
function download(content,type,name){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}$('#backup').onclick=()=>download(JSON.stringify(state,null,2),'application/json','iid-kpi-2027.json');$('#export').onclick=()=>{let cell=v=>'"'+String(v??'').replaceAll('"','""')+'"';download('\ufeff'+[['KPI','Cấp','Bộ phận','Owner','Trọng số','Mục tiêu','Đơn vị','Tháng','Thực tế','Hoàn thành %','Nguồn','Ghi chú'],...state.kpis.map(k=>[k.name,k.level,k.team,k.owner,k.weight,k.target,k.unit,month,actual(k),score(k),k.source,k.updates[month]?.note])].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8',`iid-kpi-2027-thang-${month}.csv`)};
function validateImport(s){if(!s||!Array.isArray(s.kpis)||!s.reviews||typeof s.reviews!=='object'||!s.mix)return false;let ids=new Set();for(let k of s.kpis){if(!k||typeof k.id!=='string'||ids.has(k.id)||!['IID','Bộ phận','Cá nhân'].includes(k.level)||!['up','down'].includes(k.direction)||!Number.isFinite(k.target)||k.target<=0||!Number.isFinite(k.weight)||k.weight<0||k.weight>100||!k.updates||typeof k.updates!=='object'||['name','owner','team','unit','source','frequency'].some(n=>typeof k[n]!=='string'))return false;ids.add(k.id);for(let [m,u]of Object.entries(k.updates))if(!/^([1-9]|1[0-2])$/.test(m)||!u||!Number.isFinite(u.actual)||u.actual<0||typeof u.note!=='string')return false;}for(let k of s.kpis)if(k.level!=='IID'&&!s.kpis.some(p=>p.id===k.parent&&p.level===(k.level==='Cá nhân'?'Bộ phận':'IID')))return false;for(let [key,bounds]of [['department',[[30,70],[30,70]]],['personal',[[20,40],[30,50],[20,40]]]]){let a=s.mix[key];if(!Array.isArray(a)||a.length!==bounds.length||a.some((v,i)=>!Number.isFinite(v)||v<bounds[i][0]||v>bounds[i][1])||a.reduce((x,y)=>x+y,0)!==100)return false}return Object.values(s.reviews).every(r=>r&&typeof r.note==='string'&&['Nháp','Đã đánh giá'].includes(r.status))}
$('#import').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;let s=JSON.parse(await f.text());if(!validateImport(s))throw Error();if(!confirm('Thay toàn bộ dữ liệu hiện tại bằng bản sao này?'))return;state=s;save();render();toast('Đã nhập dữ liệu')}catch{toast('Bản sao không đúng định dạng KPI.')}finally{e.target.value=''}};render();
